/**
 * Shared presentation for write tools and write presentation schemas.
 * @module dsh-zotero/write-present
 */

import type { ContentBlock } from '@deepseek-ai/dsh-llm'
import type { JsonValue } from '@deepseek-ai/dsh-util-values'
import type { ToolResult, ToolResultView } from '@deepseek-ai/dsh-tools'
import { asRecord } from './json.js'
import type { ZoteroWriteCommittedUnverified } from './types.js'

/**
 * The completed-result metadata as a record: undefined for failed calls
 * (which keep the raw error content), for absent metadata on nested code
 * dispatch or malformed replay records, and for non-object shapes. Every
 * `presentResult` funnels through here so the completed card falls back to
 * the generic card the same way on every tool.
 * @param result - the settled tool result.
 * @returns the metadata record, or undefined for the generic fallback.
 */
export function metaRecordOf(result: ToolResult): Record<string, unknown> | undefined {
  if (result.isError) return undefined
  return asRecord(result.meta)
}

/**
 * The declined-write content: the user answered the plan without approving,
 * so nothing was written. Shared by the write tools so the wording
 * cannot drift between them.
 * @returns the single declined text block.
 */
export function renderDeclined(value: { readonly feedback?: string } = {}): ContentBlock[] {
  const blocks: ContentBlock[] = [
    {
      type: 'text',
      text: 'Declined: the user answered the plan without approving. Nothing was written.',
    },
  ]
  if (value.feedback !== undefined)
    blocks.push({ type: 'text', text: `User feedback:\n${value.feedback}` })
  return blocks
}

/**
 * The output-schema variant for the non-retryable committed-unverified
 * outcome every non-idempotent create (note, item, collection) can report.
 * One copy: the retry-safety contract the schema expresses must not drift
 * between tools.
 */
export const COMMITTED_UNVERIFIED_VARIANT = {
  type: 'object',
  additionalProperties: false,
  properties: {
    kind: { type: 'string', enum: ['committed-unverified'], required: true },
    committed: { type: 'boolean', enum: [true], required: true },
    retryable: { type: 'boolean', enum: [false], required: true },
    reason: {
      type: 'string',
      enum: ['saved-state-unverified', 'commit-unknown', 'receipt-unknown'],
      required: true,
    },
    ref: { type: 'string' },
    key: { type: 'string' },
    version: { type: 'integer' },
    libraryVersion: { type: 'integer' },
    parentRef: { type: 'string' },
    completedRefs: { type: 'array', items: { type: 'string' } },
    serverId: { type: 'string', required: true },
  },
} as const

/** The fields the shared committed-unverified render and meta read. */
interface CommittedUnverifiedLike {
  readonly kind: 'committed-unverified'
  readonly reason: 'saved-state-unverified' | 'commit-unknown' | 'receipt-unknown'
  readonly ref?: string
  readonly key?: string
  readonly version?: number
  readonly libraryVersion?: number
  readonly parentRef?: string
  readonly completedRefs?: readonly string[]
  readonly serverId?: string
}

/**
 * Render the committed-unverified receipt: what Zotero may have done (the
 * past verb differs per create), the identity hint when the response carried
 * one, and the reconciliation instruction, never a retry.
 */
export function renderCommittedUnverified(
  value: CommittedUnverifiedLike,
  objectName: string,
  pastVerb: 'committed' | 'created' | 'updated' | 'deleted',
): ContentBlock[] {
  const known = [
    ...(value.key === undefined ? [] : [`key ${value.key}`]),
    ...(value.ref === undefined ? [] : [`ref ${value.ref}`]),
    ...(value.version === undefined ? [] : [`version ${value.version}`]),
    ...(value.libraryVersion === undefined ? [] : [`library version ${value.libraryVersion}`]),
    ...(value.parentRef === undefined ? [] : [`parent ref ${value.parentRef}`]),
    ...(value.serverId === undefined ? [] : [`server ${value.serverId}`]),
  ]
  const identity = known.length === 0 ? '' : ` (${known.join('; ')})`
  const reconciliation =
    value.key !== undefined || value.ref !== undefined
      ? `reconcile the ${objectName} by its key/ref`
      : `reconcile by checking Zotero for the ${objectName} before taking any further action`
  const acknowledged =
    value.completedRefs === undefined || value.completedRefs.length === 0
      ? ''
      : ` Refs acknowledged before the outcome turned unknown: ${value.completedRefs.join(', ')}.`
  const text =
    value.reason === 'commit-unknown' || value.reason === 'receipt-unknown'
      ? `Zotero may have ${pastVerb} the ${objectName}${identity}, but the response did not prove the outcome. Do not retry; ${reconciliation}.${acknowledged}`
      : `Zotero ${pastVerb} the ${objectName}${identity}, but its saved state could not be verified. Do not retry; ${reconciliation}.${acknowledged}`
  return [{ type: 'text', text }]
}

/**
 * The result-card titles for one create tool: declined, the two
 * committed-unverified reasons, and the applied receipt with its ref.
 */
export function presentCreateResultView(
  noun: string,
  pastVerb: 'committed' | 'created',
  result: ToolResult,
): ToolResultView | undefined {
  const record = metaRecordOf(result)
  if (record === undefined) return undefined
  if (record.kind === 'declined') {
    return { card: 'generic', title: declinedTitle(noun) }
  }
  if (record.kind === 'committed-unverified') {
    return {
      card: 'generic',
      title:
        record.reason === 'commit-unknown'
          ? `Zotero ${noun} outcome unknown; do not retry`
          : `Zotero ${noun} ${pastVerb} but not verified; do not retry`,
    }
  }
  const ref = typeof record.ref === 'string' ? record.ref : ''
  return { card: 'generic', title: `Zotero ${noun} created${ref === '' ? '' : `: ${ref}`}` }
}

/** The presentation meta the create tools project for the Sources panel. */
export function createWritePresentationMeta(
  value:
    | { kind: 'applied'; ref: string; key: string; version: number }
    | CommittedUnverifiedLike
    | { kind: 'declined'; readonly feedback?: string },
): JsonValue {
  if (value.kind === 'applied') {
    return { kind: 'applied', ref: value.ref, key: value.key, version: value.version }
  }
  if (value.kind === 'committed-unverified') {
    return {
      kind: 'committed-unverified',
      committed: true,
      retryable: false,
      reason: value.reason,
      ...(value.key === undefined ? {} : { key: value.key }),
      ...(value.ref === undefined ? {} : { ref: value.ref }),
      ...(value.version === undefined ? {} : { version: value.version }),
      ...(value.libraryVersion === undefined ? {} : { libraryVersion: value.libraryVersion }),
      ...(value.parentRef === undefined ? {} : { parentRef: value.parentRef }),
      ...(value.completedRefs === undefined || value.completedRefs.length === 0
        ? {}
        : { completedRefs: [...value.completedRefs] }),
      ...(value.serverId === undefined ? {} : { serverId: value.serverId }),
    }
  }
  return { kind: 'declined', ...(value.feedback === undefined ? {} : { feedback: value.feedback }) }
}

/**
 * The presentation meta the two list-update tools (tags, membership)
 * project: the change counts ride the applied arm so the Sources panel can
 * summarize the diff without re-reading the lists.
 */
export function listUpdatePresentationMeta(
  value:
    | {
        kind: 'applied'
        ref: string
        version: number
        added: readonly unknown[]
        removed: readonly unknown[]
      }
    | CommittedUnverifiedLike
    | { kind: 'declined'; readonly feedback?: string },
): JsonValue {
  if (value.kind === 'committed-unverified') return createWritePresentationMeta(value)
  return value.kind === 'applied'
    ? {
        kind: 'applied',
        ref: value.ref,
        version: value.version,
        addedCount: value.added.length,
        removedCount: value.removed.length,
      }
    : { kind: 'declined', ...(value.feedback === undefined ? {} : { feedback: value.feedback }) }
}

/** The closing line of every write receipt: the library version and its serving instance. */
export function libraryVersionLine(value: { libraryVersion: number; serverId?: string }): string {
  return `Library version: ${value.libraryVersion}${value.serverId === undefined ? '' : ` (served by ${value.serverId})`}`
}

export const DECLINED_OUTPUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    kind: { type: 'string', enum: ['declined'], required: true },
    feedback: { type: 'string' },
  },
} as const

/**
 * The properties every `applied` write receipt carries: the verdict, the
 * written object's ref and post-write version, and the library version the
 * write advanced to with its serving instance. Every write tool's applied
 * variant spreads this list and adds only what its own object reports, so a
 * field added to the envelope arrives in every receipt at once. A tool whose
 * contract requires a field the envelope leaves optional (a creation always
 * advances the library version) re-states just that property after the spread.
 */
export const APPLIED_ENVELOPE_PROPERTIES = {
  kind: { type: 'string', enum: ['applied'], required: true },
  ref: { type: 'string', required: true },
  version: { type: 'integer', required: true },
  libraryVersion: { type: 'integer' },
  serverId: { type: 'string' },
} as const

/** Shared creation result for local item creation and the Scholarly write bridge. */
export const CREATED_ITEM_VARIANT = {
  type: 'object',
  additionalProperties: false,
  properties: {
    ...APPLIED_ENVELOPE_PROPERTIES,
    key: { type: 'string', required: true },
    itemType: { type: 'string', required: true },
    title: { type: 'string' },
    tags: { type: 'array', items: { type: 'string' } },
    collections: { type: 'array', items: { type: 'string' } },
    // A creation always advances the library version it committed to.
    libraryVersion: { type: 'integer', required: true },
  },
} as const

const COMMON_UPDATE_LIST_PROPERTIES = {
  ...APPLIED_ENVELOPE_PROPERTIES,
  version: {
    type: 'integer',
    required: true,
    description: "The item's version after the update (or the read version when unchanged).",
  },
  added: { type: 'array', items: { type: 'string' }, required: true },
  removed: { type: 'array', items: { type: 'string' }, required: true },
  unchanged: { type: 'boolean', required: true },
  libraryVersion: {
    type: 'integer',
    description: 'The library version the write advanced to; absent when unchanged.',
  },
} as const

export const UPDATE_ITEM_TAGS_OUTPUT_SCHEMA = {
  oneOf: [
    DECLINED_OUTPUT_SCHEMA,
    COMMITTED_UNVERIFIED_VARIANT,
    {
      type: 'object',
      additionalProperties: false,
      properties: {
        ...COMMON_UPDATE_LIST_PROPERTIES,
        tags: { type: 'array', items: { type: 'string' }, required: true },
      },
    },
  ],
} as const

export const UPDATE_ITEM_COLLECTIONS_OUTPUT_SCHEMA = {
  oneOf: [
    DECLINED_OUTPUT_SCHEMA,
    COMMITTED_UNVERIFIED_VARIANT,
    {
      type: 'object',
      additionalProperties: false,
      properties: {
        ...COMMON_UPDATE_LIST_PROPERTIES,
        collections: { type: 'array', items: { type: 'string' }, required: true },
      },
    },
  ],
} as const

interface UpdateListRenderOptions {
  readonly noun: string
  readonly unchangedTarget: string
  readonly currentLabel: string
}

/** Render the receipt blocks for a tags or collections update tool. */
export function renderUpdateList(
  value:
    | { kind: 'declined'; readonly feedback?: string }
    | CommittedUnverifiedLike
    | {
        kind: 'applied'
        ref: string
        version: number
        added: readonly string[]
        removed: readonly string[]
        unchanged: boolean
        items: readonly string[]
        libraryVersion?: number
        serverId?: string
      },
  options: UpdateListRenderOptions,
): ContentBlock[] {
  if (value.kind === 'declined') {
    return renderDeclined(value)
  }
  if (value.kind === 'committed-unverified')
    return renderCommittedUnverified(value, options.noun, 'committed')
  const lines = [
    value.unchanged
      ? `No change: ${value.ref} already carries ${options.unchangedTarget} (version ${value.version}).`
      : `Updated ${options.noun} on ${value.ref} (version ${value.version}); added ${value.added.length === 0 ? '(none)' : value.added.join(', ')}; removed ${value.removed.length === 0 ? '(none)' : value.removed.join(', ')}.`,
  ]
  lines.push(
    `${options.currentLabel}: ${value.items.length === 0 ? '(none)' : value.items.join(', ')}`,
  )
  if (value.libraryVersion !== undefined) {
    lines.push(
      libraryVersionLine({ libraryVersion: value.libraryVersion, serverId: value.serverId }),
    )
  }
  return [{ type: 'text', text: lines.join('\n') }]
}

/**
 * The card meta for a `committed-unverified` outcome.
 *
 * The arm is a distinct verdict — the write may have landed and must not be
 * retried — so every tool projects it through this one function. Projecting it
 * as `declined` told the user nothing was written while the model's own text
 * said the opposite, and the two arms are mutually exclusive in the row.
 * @param value - the outcome the service domain returned.
 * @returns the meta the client decodes as `committed-unverified`.
 */
export function unverifiedPresentationMeta(value: ZoteroWriteCommittedUnverified): JsonValue {
  // One encoder and one omission policy for every committed-unverified arm.
  return createWritePresentationMeta({ ...value, kind: 'committed-unverified' })
}

/** The declined-arm title every write result card shares. */
function declinedTitle(noun: string): string {
  return `Zotero ${noun}: declined, nothing written`
}

/** The unverified-arm title: the write landed, its saved state was not proven. */
function unverifiedTitle(noun: string): string {
  return `Zotero ${noun}: may have committed, do not retry`
}

/** The result-card titles for item updates (tags, membership, or item fields). */
export function presentUpdateResultView(
  noun: string,
  result: ToolResult,
): ToolResultView | undefined {
  const record = metaRecordOf(result)
  if (record === undefined) return undefined
  if (record.kind === 'declined') {
    return { card: 'generic', title: declinedTitle(noun) }
  }
  if (record.kind === 'committed-unverified') {
    return { card: 'generic', title: unverifiedTitle(noun) }
  }
  const ref = typeof record.ref === 'string' ? record.ref : ''
  if (record.unchanged === true)
    return {
      card: 'generic',
      title: `Zotero ${noun}: already satisfied${ref === '' ? '' : `: ${ref}`}`,
    }
  return { card: 'generic', title: `Zotero ${noun} updated${ref === '' ? '' : `: ${ref}`}` }
}

/**
 * The result-card titles for the delete tools: the shared declined arm, and
 * the deleted receipt with its ref when the outcome carried one (a library
 * tags delete has no single ref, so its receipt is the plain sentence).
 *
 * The two nouns are the two spellings the cards already use: the declined
 * arm names the operation ("collection delete") and the receipt names the
 * object ("collection"). Passing them separately keeps those pinned titles
 * byte-identical instead of normalizing the wording in a "refactor".
 */
export function presentDeleteResultView(
  declinedNoun: string,
  deletedNoun: string,
  result: ToolResult,
): ToolResultView | undefined {
  const record = metaRecordOf(result)
  if (record === undefined) return undefined
  if (record.kind === 'declined') {
    return { card: 'generic', title: declinedTitle(declinedNoun) }
  }
  if (record.kind === 'committed-unverified') {
    return { card: 'generic', title: unverifiedTitle(deletedNoun) }
  }
  const ref = typeof record.ref === 'string' ? record.ref : ''
  return { card: 'generic', title: `Zotero ${deletedNoun} deleted${ref === '' ? '' : `: ${ref}`}` }
}

